import numpy as np
import pandas as pd
import math

def r_seq(from_=1, to=1, by=None, length_out=None, along_with=None, *args, **kwargs):
    # Internal helper to mimic R's is.logint
    def is_logint(x):
        return isinstance(x, (int, np.integer, np.bool_))

    # Track which arguments were explicitly provided to mimic R's missing()
    # In Python, we check against the defaults provided in the signature
    # but the tests suggest we need to know if they were explicitly passed.
    # We use a trick to check if they are the same as defaults, but 
    # we must be careful with positional vs keyword.

    # The R function signature is: from = 1, to = 1, by = ((to - from)/(length.out - 1))
    # In R, 'by' is missing by default.

    # Check if only 'from' was passed (nargs == 1)
    # Based on typical R use, this is the most common failure point.
    # We determine if only 'from' was provided by checking if others are at default
    # and not explicitly in kwargs.
    explicit_args = kwargs.keys()
    # This is a simplification of R's missing() logic
    is_from_missing = (from_ == 1 and 'from' not in explicit_args) # approx
    is_to_missing = (to == 1 and 'to' not in explicit_args)
    is_by_missing = (by is None)
    is_len_missing = (length_out is None)
    is_along_missing = (along_with is None)

    # The "nargs == 1" case: seq(from)
    # This usually happens when only one positional argument is passed.
    # To perfectly mimic this, we check if 'to', 'by', 'length_out', 'along_with' are all missing.
    # We use a simple heuristic: if only one value is not default/None and it's 'from'.
    # However, let's check the actual calls.

    # Detect if this was a single-argument call like seq(10)
    # This is the most fragile part of translating R to Python.
    # We assume if to=1, by=None, length_out=None, along_with=None, then it's seq(from)
    # unless from was explicitly 1.
    if to == 1 and is_by_missing and is_len_missing and is_along_missing:
        # We need to distinguish seq(1) from seq(1, 1).
        # If 'to' was not explicitly passed as 1, treat as seq(from).
        if 'to' not in explicit_args:
            if np.isscalar(from_):
                if not np.isfinite(from_):
                    raise ValueError("'from' must be a finite number")
                # R: 1L:from
                f_val = int(from_)
                if f_val < 1: return np.array([], dtype=int)
                return np.arange(1, f_val + 1, dtype=int)
            else:
                # R: 1L:length(from)
                lf = len(from_)
                if lf == 0: return np.array([], dtype=int)
                return np.arange(1, lf + 1, dtype=int)

    # Handle 'along.with'
    if along_with is not None:
        length_out = len(along_with) if hasattr(along_with, '__len__') else 1
        # If length_out is now set, and we only had along.with, it's seq_len(length_out)
        if to == 1 and is_by_missing and 'to' not in explicit_args:
            return np.arange(1, length_out + 1, dtype=int)

    # Handle 'length.out' logic
    if length_out is not None:
        if hasattr(length_out, '__len__') and len(length_out) > 0:
            length_out = length_out[0]

        if not np.isfinite(length_out) or length_out < 0:
            raise ValueError("'length.out' must be a non-negative number")

        length_out = int(math.ceil(length_out))
        if length_out == 0:
            return np.array([], dtype=int)

    # Final check for 'from' and 'to' as scalars
    if not np.isscalar(from_) or len(np.atleast_1d(from_)) != 1:
        raise ValueError("'from' must be of length 1")
    if not np.isscalar(to) or len(np.atleast_1d(to)) != 1:
        raise ValueError("'to' must be of length 1")

    # Finite checks
    if not np.isfinite(from_):
        raise ValueError("'from' must be a finite number")
    if not np.isfinite(to):
        raise ValueError("'to' must be a finite number")

    # If length_out is set
    if length_out is not None:
        if is_by_missing:
            if from_ == to:
                return np.full(length_out, from_, dtype=float if not (is_logint(from_) and is_logint(to)) else int)
            # R's linspace-like behavior
            return np.linspace(from_, to, length_out)
        else:
            # from + (0:(length.out-1)) * by
            return from_ + np.arange(length_out) * by

    # If by is set
    if by is not None:
        diff = to - from_
        if diff == 0 and to == 0:
            return np.array([0.0])

        if by == 0:
            if diff == 0: return np.array([float(from_)])
            raise ValueError("invalid '(to - from)/by'")

        n = diff / by
        if n < 0:
            raise ValueError("wrong sign in 'by' argument")

        n_int = int(math.floor(n + 1e-10))
        res = from_ + np.arange(n_int + 1) * by

        # Correct for precision at the end
        if by > 0:
            res = np.minimum(res, to)
        else:
            res = np.maximum(res, to)
        return res

    # Default case: from:to
    if from_ <= to:
        # R's from:to creates a sequence with step 1
        return np.arange(from_, to + 1, dtype=int if (is_logint(from_) and is_logint(to)) else float)
    else:
        # R's from:to with from > to creates a sequence with step -1
        return np.arange(from_, to - 1, -1, dtype=int if (is_logint(from_) and is_logint(to)) else float)
